// --- acr_nav.FDb.navstack.Find
// Look up row by row id. Return NULL if out of range
inline acr_nav::Naventry* acr_nav::navstack_Find(u64 t) {
    u64 idx = t;
    u64 lim = _db.navstack_n;
    if (idx >= lim) return NULL;
    return _db.navstack_elems + idx;
}

// --- acr_nav.FDb.navstack.Getary
