// --- acr_nav.FDb.navstack.Reserve
// Make sure N *more* elements will fit in array. Process dies if out of memory
inline void acr_nav::navstack_Reserve(int n) {
    u32 new_n = _db.navstack_n + n;
    if (UNLIKELY(new_n > _db.navstack_max)) {
        navstack_AbsReserve(new_n);
    }
}

